import{_ as l,K as r,a as o,c as p,ac as n,b as e,q as i,k as s}from"./chunks/framework.BSuaGltH.js";const T=JSON.parse('{"title":"国际象棋：开局原则与基础残局","description":"先学发展和王安全，再用后王对单王的局面练习将死与避免逼和。","frontmatter":{"title":"国际象棋：开局原则与基础残局","description":"先学发展和王安全，再用后王对单王的局面练习将死与避免逼和。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"国际象棋入门","summary":"先学发展和王安全，再用后王对单王的局面练习将死与避免逼和。","status":"active","related":[{"title":"国际象棋：棋子走法、特殊规则与胜负","link":"/life/personal/chess/international-chess/rules","kind":"棋类入门","scope":"general","audience":"general"},{"title":"国际象棋：双攻、牵制与串击","link":"/life/personal/chess/international-chess/tactics","kind":"棋类入门","scope":"general","audience":"general"},{"title":"国际象棋：检查威胁与减少失误","link":"/life/personal/chess/international-chess/review","kind":"棋类入门","scope":"general","audience":"general"}],"prev":{"text":"国际象棋：双攻、牵制与串击","link":"/life/personal/chess/international-chess/tactics"},"next":{"text":"国际象棋：检查威胁与减少失误","link":"/life/personal/chess/international-chess/review"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"国际象棋：双攻、牵制与串击","link":"/life/personal/chess/international-chess/tactics"},"next":{"text":"国际象棋：检查威胁与减少失误","link":"/life/personal/chess/international-chess/review"}},"headers":[],"relativePath":"life/personal/chess/international-chess/opening-endgame.md","filePath":"life/personal/chess/international-chess/opening-endgame.md"}'),c={name:"life/personal/chess/international-chess/opening-endgame.md"},d={class:"chess-example"},h={class:"chess-figure"},g={class:"chess-example"},f={class:"chess-figure"};function _(u,a,b,m,k,x){const t=r("ArticleImage");return o(),p("div",null,[a[2]||(a[2]=n('<h1 id="国际象棋-开局原则与基础残局" tabindex="-1">国际象棋：开局原则与基础残局 <a class="header-anchor" href="#国际象棋-开局原则与基础残局" aria-label="Permalink to &quot;国际象棋：开局原则与基础残局&quot;">​</a></h1><p>开局和残局需要不同思路：开局先让棋子工作、保护王；残局棋子变少，王也常要参与战斗，但仍不能走进攻击范围。</p><h2 id="开局先解决三件事" tabindex="-1">开局先解决三件事 <a class="header-anchor" href="#开局先解决三件事" aria-label="Permalink to &quot;开局先解决三件事&quot;">​</a></h2><p>中心附近的兵和轻子能影响更多格子。先发展马、象，让车之间的道路逐渐打开，再在条件允许时易位保护王。不要早早把后送进敌阵，被小子反复攻击，白白让对手发展。</p><p>“控制中心”不等于每颗棋都挤在中央；可以用棋子远程控制中心格。“不要重复走同一个子”也不是禁令，若棋子受攻击或必须解将，就该再走。</p><h2 id="一段可摆的开局" tabindex="-1">一段可摆的开局 <a class="header-anchor" href="#一段可摆的开局" aria-label="Permalink to &quot;一段可摆的开局&quot;">​</a></h2>',6)),e("div",d,[e("div",h,[e("p",null,[i(t,{src:"/images/chess/chess-opening.svg",alt:"4...Nf6 后 · 白方已短易位。接下来轮白走；白王 g1，白车 f1。"})])]),a[0]||(a[0]=n(`<div class="chess-explanation"><p>从初始局面开始：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. e4   e5</span></span>
<span class="line"><span>2. Nf3  Nc6</span></span>
<span class="line"><span>3. Bc4  Bc5</span></span>
<span class="line"><span>4. O-O  Nf6</span></span></code></pre></div><p>每行白黑各一步。e4 表示白兵 e2→e4；e5 是黑兵 e7→e5。Nf3 是白马 g1→f3，攻击黑 e5 兵；Nc6 是黑马 b8→c6，保护 e5。Bc4、Bc5 分别发展双方的王翼象。O-O 是白方短易位，王到 g1，车到 f1。</p><p>这条线示范了发展和易位，不保证最佳。白方能易位，是因为 f1 的象、g1 的马已经离开，王没有走过，也未处于或经过敌方攻击。如果对手走法不同，要重新检查这些条件。</p></div>`,1))]),a[3]||(a[3]=e("h2",{id:"残局先看王能否靠近",tabindex:"-1"},[s("残局先看王能否靠近 "),e("a",{class:"header-anchor",href:"#残局先看王能否靠近","aria-label":'Permalink to "残局先看王能否靠近"'},"​")],-1)),a[4]||(a[4]=e("p",null,"单后或单车通常需要自己的王协助，才能可靠地把对方王逼到边上。不能指望后不停将军就自动获胜。用后限制活动区域，再让王靠近支援，比漫无目的追逐更有条理。",-1)),a[5]||(a[5]=e("p",null,"同时记住：两王之间至少要隔开一个格子的接触距离，不能相邻；王不能吃受敌方保护的后。",-1)),a[6]||(a[6]=e("h2",{id:"一步将死的完整摆法",tabindex:"-1"},[s("一步将死的完整摆法 "),e("a",{class:"header-anchor",href:"#一步将死的完整摆法","aria-label":'Permalink to "一步将死的完整摆法"'},"​")],-1)),e("div",g,[e("div",f,[e("p",null,[i(t,{src:"/images/chess/chess-mate.svg",alt:"Qb7# · 将死后的局面。黑无合法应将；b7 白后受 c6 白王保护。"})])]),a[1]||(a[1]=e("div",{class:"chess-explanation"},[e("p",null,"摆白王 c6、白后 b6、黑王 a8，轮白走，其他格空。"),e("p",null,"白后 b6→b7，记作 Qb7#。后从 b7 斜线攻击 a8 黑王；黑王去 a7 被后横线控制，去 b8 被后竖线控制；若吃 b7 白后，b7 又受白王 c6 保护，所以也不能走。黑方无其他子，因而将死。# 表示将死。"),e("p",null,[s("对照：如果白后走 c7，则黑王 a8 "),e("strong",null,"没有被将军"),s(" ，但 a7、b7、b8 都不能去，没有任何合法着法，立即逼和。多一个后却只拿和棋，是新手最值得单独练的错误。")])],-1))]),a[7]||(a[7]=n('<h2 id="兵升变前多看一手" tabindex="-1">兵升变前多看一手 <a class="header-anchor" href="#兵升变前多看一手" aria-label="Permalink to &quot;兵升变前多看一手&quot;">​</a></h2><p>白兵在 e7，若 e8 空、己王安全，可以走 e8 并升变。通常变后最有力，但不能漏掉对手下一手能不能吃掉新后，也不能忘记检查是不是把对方逼和。升变不是“先放着一颗兵，下回合再决定”。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><ol><li>示例开局 3.Bc4 后白车能直接从 h1 到 f1 吗？<strong>作为普通车步，中间 g1 已空，但若 f1 空则可能合法；这不等于易位。</strong> 王仍在 e1，易位必须按规定同时移动王车。</li><li>Qb7# 例中黑王为何不能吃后？<strong>白王 c6 保护 b7。</strong></li><li>两王单独留在棋盘，能强行将死吗？<strong>不能。</strong> 双方都无法合法控制对方所有逃格并将军，是死局。</li></ol><p>练习方法：摆好两种后的位置，交替说明“有没有将军、有哪些候选逃格”。能逐格解释，再练更远的逼边过程。</p><p>规则参照：<a href="https://handbook.fide.com/chapter/E012023" target="_blank" rel="noopener noreferrer">FIDE 官方手册</a>。局面和示范步骤为教学内容。</p>',6))])}const P=l(c,[["render",_]]);export{T as __pageData,P as default};
